@import 'c/rlySharedStyles';

:host { display: block; }
.rr-ct { display: flex; flex-wrap: wrap; align-items: center; gap: 6px 12px; padding: 8px 16px; font-size: 12px; background: #fff; border: 1px solid #e5e5e5; border-radius: 4px; box-shadow: 0 2px 2px rgba(0, 0, 0, 0.05); }
.rr-ct-title { font-size: 11px; font-weight: 700; letter-spacing: 0.04em; text-transform: uppercase; color: #5c5c5c; }
.rr-ct-list { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 4px; min-width: 0; flex: 1 1 320px; }
.rr-ct-list li { display: flex; align-items: center; gap: 8px; min-width: 0; }
.rr-ct-name { overflow-wrap: anywhere; }
.rr-grow { flex: 1 1 auto; }
.rr-weak { color: #5c5c5c; }
.rr-link { background: none; border: 0; padding: 0; color: #0b5cab; font-weight: 600; cursor: pointer; font-size: 12px; }
.rr-pill { display: inline-block; font-size: 11px; font-weight: 700; padding: 2px 9px; border-radius: 10px; white-space: nowrap; }
.rr-pill-bad { background: #feded8; color: #ba0517; }
.rr-pill-wait { background: #fef1cd; color: #a96404; }
.rr-pill-none { background: #f3f3f3; color: #5c5c5c; }
